/**
 * compose override와 edge 설정의 벡터(ADR-191 2단계 2b-2a). 기대값은 Rust로 옮기기 전 TS(`buildOverride`·`composeUpArgs`·`edge-config.ts`)가 낸 값이다.
 * 이 테스트를 옛 TS에 돌리면 "의도한 차이" 절의 테스트만 실패한다. 객체 키 순서가 YAML 글자를 정하므로 `JSON.stringify` 글자로 견준다.
 *
 * 기대값 문자열 안의 \u0001 표지는 길고 되풀이되는 부분이다. 아래 손으로 적은 값으로 펼친다(코드가 만든 값으로 펼치면 같은 값끼리 견주는 셈이다):
 *  - EG: 기본 허용 호스트 목록(닫는 대괄호 앞까지)
 *  - HC: edge의 healthcheck
 *  - PE:<직접 부를 이름 목록>: `proxyEnvironment`가 만드는 환경 변수
 */
const EG_PREFIX =
  '["registry.npmjs.org","fonts.googleapis.com","fonts.gstatic.com","repo.maven.apache.org","repo1.maven.org","maven-central.storage-download.googleapis.com","plugins.gradle.org","plugins-artifacts.gradle.org","services.gradle.org","downloads.gradle.org","github.com","release-assets.githubusercontent.com","objects.githubusercontent.com","pypi.org","files.pythonhosted.org"';
const HEALTHCHECK = {
  test: ['CMD', 'node', '-e', "require('node:net').connect(3128, '127.0.0.1').on('connect', () => process.exit(0)).on('error', () => process.exit(1))"],
  interval: '1s',
  timeout: '2s',
  retries: 30,
  start_interval: '200ms',
  start_period: '10s',
};
function proxyEnv(direct: string[]): Record<string, string> {
  const proxy = 'http://b-studio-edge:3128';
  return {
    HTTP_PROXY: proxy,
    HTTPS_PROXY: proxy,
    ALL_PROXY: proxy,
    http_proxy: proxy,
    https_proxy: proxy,
    all_proxy: proxy,
    NO_PROXY: direct.join(','),
    no_proxy: direct.join(','),
    NODE_USE_ENV_PROXY: '1',
    JAVA_TOOL_OPTIONS: `-Dhttp.proxyHost=b-studio-edge -Dhttp.proxyPort=3128 -Dhttps.proxyHost=b-studio-edge -Dhttps.proxyPort=3128 -Dhttp.nonProxyHosts=${direct.join('|')}`,
  };
}
function expand(expected: string): string {
  return expected
    .replaceAll('\u0001EG\u0001', JSON.stringify(EG_PREFIX).slice(1, -1))
    .replaceAll('\u0001HC\u0001', JSON.stringify(HEALTHCHECK))
    .replace(/\u0001PE:(.*?)\u0001/g, (_m, direct: string) => JSON.stringify(proxyEnv(JSON.parse(direct) as string[])));
}

