const asProject = (project: unknown) => project as LoadedProject;

describe('buildOverride 벡터: 옛 TS가 낸 값과 글자까지 같다(키 순서 포함)', () => {
  it.each(CASES)('$title', ({ project, id, opts, expected }) => {
    if (expected === THROWS) {
      expect(() => buildOverride(asProject(project), id, opts)).toThrow(/edge 설정 이름과 겹칩니다/);
      return;
    }
    expect(JSON.stringify(buildOverride(asProject(project), id, opts))).toBe(expand(expected));
  });

  it('YAML로 쓰면 정수 꼴 서비스 이름이 앞에 온다', () => {
    const project = asProject({ managed: [['web', { port: 3000 }], ['api', { port: 8080 }]], composeServices: ['web', '10', 'api', '2', 'db'] });
    const override = buildOverride(project, 's1');
    expect(Object.keys(override.services)).toEqual(['2', '10', 'web', 'api', 'db', 'b-studio-edge']);
    const lines = stringify(override).split('services:\n')[1]!.split('\n').filter((line) => /^ {2}\S/.test(line));
    expect(lines).toEqual(['  "2":', '  "10":', '  web:', '  api:', '  db:', '  b-studio-edge:']);
  });
});

// ── 격리 줄은 벡터와 따로 눈으로 읽을 수 있게 한 번 더 적는다. 한 줄이 바뀌면 여기가 먼저 실패한다
const ORDERS = asProject({
  managed: [
    ['web', { port: 3000 }],
    ['api', { port: 8080 }],
  ],
  composeServices: ['web', 'api', 'db'],
  secrets: [['PAYMENT_API_KEY', { services: ['api'] }], ['LEGACY_TOKEN', { services: [] }]],
  external: [['legacy-users', { source: 'external', baseUrl: 'https://u.example.com/v1', policy: { mask: [], maskPatterns: [], auth: { header: 'Authorization', secret: 'LEGACY_TOKEN', prefix: 'Bearer $' } } }]],
  egress: ['api.slack.com'],
});

describe('격리를 정하는 줄', () => {
  const override = buildOverride(ORDERS, 's1', { runtime: 'runsc', edgeScript: 'a $ b', hostPorts: { api: 54321 }, gitMask: { web: [{ type: 'bind', source: '/p/.git', target: '/app/.git', read_only: true, bind: { create_host_path: false } }] } });
  const edge = override.services[EDGE_SERVICE]!;

  it('샌드박스 네트워크는 internal이고 서비스는 거기에만 붙는다', () => {
    expect(override.networks).toEqual({ [SANDBOX_NETWORK]: { internal: true }, [EGRESS_NETWORK]: {} });
    for (const name of ['web', 'api', 'db']) {
      expect(override.services[name]!.networks).toEqual([SANDBOX_NETWORK]);
      expect(override.services[name]).not.toHaveProperty('ports');
    }
    expect(edge.networks).toEqual({ [SANDBOX_NETWORK]: { aliases: ['legacy-users'] }, [EGRESS_NETWORK]: {} });
  });

  it('공개하는 포트는 모두 루프백이고, 정한 포트가 있는 서비스만 고정한다', () => {
    expect(edge.ports).toEqual(['127.0.0.1::20000', '127.0.0.1:54321:20001']);
    for (const port of edge.ports as string[]) expect(port.startsWith('127.0.0.1:')).toBe(true);
  });

  it('시크릿 값은 null로 비워 받는 서비스에만 적고, 인증 시크릿은 edge에만 적는다', () => {
    expect(override.services.api!.environment).toHaveProperty('PAYMENT_API_KEY', null);
    expect(override.services.web!.environment).not.toHaveProperty('PAYMENT_API_KEY');
    expect(override.services.api!.environment).not.toHaveProperty('LEGACY_TOKEN');
    expect(edge.environment).toHaveProperty('LEGACY_TOKEN', null);
    expect(JSON.stringify(override)).not.toMatch(/"PAYMENT_API_KEY":"/);
  });

  it('.git 마스크 볼륨이 서비스의 volumes로 들어간다', () => {
    expect(override.services.web!.volumes).toEqual([{ type: 'bind', source: '/p/.git', target: '/app/.git', read_only: true, bind: { create_host_path: false } }]);
    expect(override.services.api).not.toHaveProperty('volumes');
  });

  it('command와 edge 환경 변수의 $는 $$로 적힌다', () => {
    expect((edge.command as string[]).at(-1)).toBe('a $$ b');
    expect(String((edge.environment as Record<string, unknown>).EDGE_EXTERNALS)).toContain('Bearer $$');
    expect(String((edge.environment as Record<string, unknown>).EDGE_EXTERNALS)).not.toMatch(/Bearer \$[^$]/);
  });

  it('서비스 이름과 사내 API 이름은 프록시를 거치지 않는다', () => {
    const environment = override.services.web!.environment as Record<string, string>;
    expect(environment.NO_PROXY).toBe('localhost,127.0.0.1,web,api,db,legacy-users');
    expect(environment.no_proxy).toBe(environment.NO_PROXY);
    expect(environment.JAVA_TOOL_OPTIONS).toContain('-Dhttp.nonProxyHosts=localhost|127.0.0.1|web|api|db|legacy-users');
    expect(environment.HTTPS_PROXY).toBe(`http://${EDGE_SERVICE}:${EDGE_PROXY_PORT}`);
  });

  it('모든 서비스가 edge의 healthcheck를 기다린다', () => {
    for (const name of ['web', 'api', 'db']) expect(override.services[name]!.depends_on).toEqual({ [EDGE_SERVICE]: { condition: 'service_healthy' } });
    expect(edge.healthcheck).toEqual(HEALTHCHECK);
  });

  it('런타임은 edge와 모든 서비스에 걸린다', () => {
    for (const name of ['web', 'api', 'db', EDGE_SERVICE]) expect(override.services[name]!.runtime).toBe('runsc');
  });

  it('사내 API가 있으면 edge에 host.docker.internal을 준다', () => {
    expect(edge.extra_hosts).toEqual(['host.docker.internal:host-gateway']);
    expect(buildOverride(asProject({ managed: [], composeServices: ['db'] }), 's1').services[EDGE_SERVICE]).not.toHaveProperty('extra_hosts');
  });

  it('edge의 자원 한도와 이미지', () => {
    expect(edge.deploy).toEqual({ resources: { limits: { memory: '128m', cpus: '0.5' } } });
    expect(edge.image).toBe(EDGE_IMAGE);
    expect(edge.labels).toEqual({ 'b-studio.sandbox': 's1', 'b-studio.service': EDGE_SERVICE });
  });
});

describe('자원 한도의 빈 값', () => {
  it('cpus가 0이거나 NaN이면 건너뛰고, 메모리가 빈 문자열이면 건너뛴다', () => {
    const project = asProject({ managed: [], composeServices: ['a', 'b', 'c'], resources: { a: { cpus: 0 }, b: { cpus: Number.NaN }, c: { memory: '' } } });
    const { services } = buildOverride(project, 's1');
    for (const name of ['a', 'b', 'c']) expect(services[name]!.deploy).toEqual({ resources: { limits: {} } });
  });
});

describe('edge-config', () => {
  it('상수', () => {
    expect(EDGE_SERVICE).toBe('b-studio-edge');
    expect(EDGE_PROXY_PORT).toBe(3128);
    expect(EDGE_IMAGE).toBe('node:22-bookworm-slim');
    expect(SANDBOX_NETWORK).toBe('b-studio-sandbox');
    expect(EGRESS_NETWORK).toBe('b-studio-egress');
    expect(JSON.stringify(DEFAULT_EGRESS_ALLOW).slice(0, -1)).toBe(EG_PREFIX);
    expect(DEFAULT_EGRESS_ALLOW).toHaveLength(15);
  });

  it('edgePortFor: 서비스 순서, 같은 이름이면 처음 자리, 없으면 던진다', () => {
    const project = asProject({ managed: [['a', { port: 1 }], ['b', { port: 2 }], ['a', { port: 3 }]] });
    expect([edgePortFor(project, 'a'), edgePortFor(project, 'b')]).toEqual([20000, 20001]);
    expect(() => edgePortFor(project, 'c')).toThrow("'c'은(는) managed 서비스가 아닙니다");
  });

  it('directHosts: 로컬, 서비스, 사내 API 순서', () => {
    const project = asProject({ managed: [], external: [['x', {}], ['y', {}]] });
    expect(directHosts(project, ['web', 'db'])).toEqual(['localhost', '127.0.0.1', 'web', 'db', 'x', 'y']);
    expect(directHosts(asProject({ managed: [] }), [])).toEqual(['localhost', '127.0.0.1']);
  });

  it('proxyEnvironment: 키 순서와 값', () => {
    const environment = proxyEnvironment(['localhost', 'web']);
    expect(Object.keys(environment)).toEqual(['HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'http_proxy', 'https_proxy', 'all_proxy', 'NO_PROXY', 'no_proxy', 'NODE_USE_ENV_PROXY', 'JAVA_TOOL_OPTIONS']);
    expect(environment).toEqual(proxyEnv(['localhost', 'web']));
  });

  it('edgeEnvironment: 값을 그대로 담는다($를 겹치지 않는다)', () => {
    const environment = edgeEnvironment(ORDERS, ['web', 'api', 'db']);
    expect(Object.keys(environment)).toEqual(['EDGE_MAIN', 'EDGE_FORWARDS', 'EDGE_EGRESS', 'EDGE_CALLERS', 'EDGE_EXTERNALS']);
    expect(environment.EDGE_MAIN).toBe('1');
    expect(environment.EDGE_FORWARDS).toBe('20000=web:3000,20001=api:8080');
    expect(environment.EDGE_EGRESS).toBe(`${EG_PREFIX},"api.slack.com"]`);
    expect(environment.EDGE_CALLERS).toBe('web,api,db');
    expect(environment.EDGE_EXTERNALS).toBe('[{"name":"legacy-users","baseUrl":"https://u.example.com/v1","policy":{"mask":[],"maskPatterns":[],"auth":{"header":"Authorization","secret":"LEGACY_TOKEN","prefix":"Bearer $"}}}]');
  });

  it('JSON.stringify와 같은 이스케이프: 따옴표·역슬래시·제어 문자는 막고 U+2028·슬래시·DEL은 그대로', () => {
    const project = asProject({ managed: [], egress: ['a"b\\c\n\t\u0001/ \u007f😀'] });
    expect(edgeEnvironment(project, []).EDGE_EGRESS).toBe(`${EG_PREFIX},${JSON.stringify('a"b\\c\n\t\u0001/ \u007f😀')}]`);
  });

  it('값이 없는 속성은 JSON에서 빠지고 NaN·-0은 JSON.stringify처럼 쓴다', () => {
    const project = asProject({ managed: [], external: [['x', { baseUrl: undefined, policy: { n: Number.NaN, z: -0, big: 1e21, small: 1e-7, u: undefined, '2': 'b', '1': 'a' } }]] });
    expect(edgeEnvironment(project, []).EDGE_EXTERNALS).toBe('[{"name":"x","policy":{"1":"a","2":"b","n":null,"z":0,"big":1e+21,"small":1e-7}}]');
  });
});

describe('composeUpArgs', () => {
  it('목록이 없으면 빈 배열, 있으면 --no-deps와 이름 순 중복 없는 목록', () => {
    expect(composeUpArgs(undefined, EDGE_SERVICE)).toEqual([]);
    expect(composeUpArgs([], EDGE_SERVICE)).toEqual(['--no-deps', EDGE_SERVICE]);
    expect(composeUpArgs(['web', 'db', 'web', EDGE_SERVICE], EDGE_SERVICE)).toEqual(['--no-deps', EDGE_SERVICE, 'db', 'web']);
  });

  it('이름 순은 UTF-16 코드 단위 순서다(대문자가 소문자 앞, 서로게이트 쌍이 U+FFFF 앞)', () => {
    expect(composeUpArgs(['b', 'B', 'a', '😀', '￿', 'é'], 'z')).toEqual(['--no-deps', 'B', 'a', 'b', 'z', 'é', '😀', '￿']);
  });
});

describe('공개 URL 자리 표시자 두 구현(spec의 TS와 Rust)이 같게 읽는다', () => {
  it.each([
    ['${b-studio:services.api.publicUrl}/v1', { api: 8080 }, 'http://127.0.0.1:8080/v1'],
    ['${b-studio:services.api.publicUrl} ${b-studio:services.web.publicUrl}', { api: 1 }, 'http://127.0.0.1:1 ${b-studio:services.web.publicUrl}'],
    ['${b-studio:services.Api.publicUrl}', { Api: 1 }, '${b-studio:services.Api.publicUrl}'],
    ['${b-studio:services.é.publicUrl}', { é: 1 }, '${b-studio:services.é.publicUrl}'],
    ['$${b-studio:services.api.publicUrl}', { api: 2 }, '$http://127.0.0.1:2'],
    ['${b-studio:services.a-b-.publicUrl}${b-studio:services.-a.publicUrl}', { 'a-b-': 3, '-a': 4 }, 'http://127.0.0.1:3${b-studio:services.-a.publicUrl}'],
  ])('%s', (value, ports, expected) => {
    expect(native.resolvePublicUrlPlaceholders(value, JSON.stringify(ports))).toBe(expected);
  });
});

// ── 의도한 차이: 옛 TS에서는 실패한다. 모두 막는 쪽(던지거나, 정해진 포트가 아닌 자동 배정)으로만 다르다
describe('의도한 차이', () => {
  const small = asProject({ managed: [['web', { port: 3000 }], ['api', { port: 8080 }]], composeServices: ['web', 'api'] });

  it.each([1.5, -1, 65_536, Number.NaN, Number.POSITIVE_INFINITY])('호스트 포트 %s는 받지 않는다(옛 TS는 그대로 이어 붙였다)', (port) => {
    expect(() => buildOverride(small, 's1', { hostPorts: { api: port } })).toThrow('hostPorts.api');
  });

  it('호스트 포트 0과 65535는 받는다', () => {
    expect(buildOverride(small, 's1', { hostPorts: { web: 0, api: 65_535 } }).services[EDGE_SERVICE]!.ports).toEqual(['127.0.0.1:0:20000', '127.0.0.1:65535:20001']);
  });

  it('constructor 같은 상속된 이름을 hostPorts에 있다고 읽지 않는다(옛 TS는 함수의 글자를 주소에 넣었다)', () => {
    const project = asProject({
      managed: [['constructor', { port: 80 }], ['api', { port: 1 }]],
      composeServices: ['constructor', 'api'],
      publicUrlRefs: [{ service: 'api', envKey: 'U', template: '${b-studio:services.constructor.publicUrl}/x', targetService: 'constructor' }],
    });
    const { services } = buildOverride(project, 's1');
    expect(services[EDGE_SERVICE]!.ports).toEqual(['127.0.0.1::20000', '127.0.0.1::20001']);
    expect(services.api!.environment).not.toHaveProperty('U');
  });

  it.each([
    ['서비스 이름이 문자열이 아니다', { managed: [], composeServices: ['a', 5] }],
    ['managed 포트가 수가 아니다', { managed: [['a', { port: '80' }]] }],
    ['시크릿을 받는 서비스 목록이 없다', { managed: [], secrets: [['K', {}]] }],
    ['사내 API의 정책이 없다', { managed: [], external: [['x', { baseUrl: 'http://x' }]] }],
    ['인증 시크릿 이름이 문자열이 아니다', { managed: [], external: [['x', { baseUrl: 'http://x', policy: { auth: { header: 'H' } } }]] }],
    ['자원 한도가 객체가 아니다', { managed: [], resources: { a: 'x' } }],
    ['cpus가 수가 아니다', { managed: [], resources: { a: { cpus: '2' } } }],
    ['공개 URL 참조에 필드가 없다', { managed: [], publicUrlRefs: [{ service: 'a' }] }],
  ])('모양이 어긋난 입력은 던진다: %s', (_label, project) => {
    expect(() => buildOverride(asProject(project), 's1')).toThrow();
  });

  it('런타임이 문자열이 아니면 던진다', () => {
    expect(() => buildOverride(small, 's1', { runtime: 5 as unknown as string })).toThrow('runtime');
  });

  it('gitMask의 값이 배열이 아니면 던진다', () => {
    expect(() => buildOverride(small, 's1', { gitMask: { web: 'x' as never } })).toThrow('gitMask.web');
  });

  it('짝 없는 서로게이트는 U+FFFD로 읽는다(JS 문자열 한 글자가 다른 글자로 바뀐다)', () => {
    const environment = edgeEnvironment(asProject({ managed: [], egress: ['a\ud800b'] }), []);
    expect(environment.EDGE_EGRESS).toBe(`${EG_PREFIX},"a�b"]`);
  });
});
